// Loopback-only test server. A single fixture URL drops the transport so WebKit's
// real worker/network fallback is exercised without its synthetic offline mode.
import {createServer} from 'node:http';import {readFile,stat} from 'node:fs/promises';import {resolve,extname,sep} from 'node:path';import {fileURLToPath} from 'node:url';
const root=fileURLToPath(new URL('../../',import.meta.url)),types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json','.webmanifest':'application/manifest+json','.png':'image/png','.jpg':'image/jpeg','.webp':'image/webp','.svg':'image/svg+xml','.woff2':'font/woff2','.ttf':'font/ttf'};
const blocked=new Set();
createServer(async(req,res)=>{try{const url=new URL(req.url,'http://127.0.0.1');if(url.pathname==='/__test__/transport'&&req.method==='POST'){const id=url.searchParams.get('id');if(!id||!/^[a-z0-9-]+$/.test(id)){res.writeHead(400).end();return;}if(url.searchParams.get('offline')==='1')blocked.add(id);else blocked.delete(id);res.writeHead(204).end();return;}if(url.pathname==='/'&&blocked.has(url.searchParams.get('__pwa_network_test'))){req.socket.destroy();return;}const path=decodeURIComponent(url.pathname),file=resolve(root,'.'+(path==='/'?'/index.html':path));if(!file.startsWith(root.endsWith(sep)?root:root+sep)||path.split('/').some(p=>p.startsWith('.'))||path.startsWith('/node_modules/')){res.writeHead(403).end();return;}if(!(await stat(file)).isFile()){res.writeHead(404).end();return;}res.writeHead(200,{'Content-Type':types[extname(file)]||'application/octet-stream','Cache-Control':'no-store'}).end(await readFile(file));}catch{res.writeHead(404).end();}}).listen(4173,'127.0.0.1',()=>console.log('iPhone fixture server on loopback port 4173'));
